script:
const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto");
const run=RUN_CONFIG,cwd=process.cwd(),prefix=cwd+"/docs/coordinator/worktree-completion/evidence/dcc1-parity-observer-proof-"+run.label;
const sha=(b,a="sha256")=>crypto.createHash(a).update(b).digest("hex");
const git=(...a)=>cp.execFileSync("git",a,{cwd,encoding:"utf8"});
const index=git("write-tree").trim();if(index!=="ae00723e05d20a6c87d0ada500fc77a456870ea9")throw Error("index drift");
const files=git("ls-files","-s").trimEnd().split("\n").filter(x=>!x.includes("\tdocs/coordinator/worktree-completion/")).map(line=>{const [meta,path]=line.split("\t"),[mode,expected,stage]=meta.split(" ");const b=mode==="120000"?Buffer.from(fs.readlinkSync(path)):fs.readFileSync(path);const blob=sha(Buffer.concat([Buffer.from("blob "+b.length+"\0"),b]),"sha1");const admitted=run.inputs[path]===undefined?expected:run.inputs[path];if(stage!=="0"||blob!==admitted)throw Error("unadmitted input "+path+" "+blob);return {path,mode,bytes:b.length,sha256:sha(b),blob,indexBlob:expected}});
const inputs=new Map(files.map(x=>[x.path,x]));const stream=git("ls-tree","-r","--full-tree",index).split("\n").filter(x=>x&&!/\tdocs\/coordinator\/worktree-completion\/(reports|evidence|handoffs)\//.test(x)).map(line=>{const [meta,path]=line.split("\t");const row=inputs.get(path);if(!row)throw Error(path);return meta.replace(/[0-9a-f]{40}$/,row.blob)+"\t"+path}).join("\n")+"\n";
const pre=JSON.parse(fs.readFileSync("docs/coordinator/worktree-completion/evidence/dcc1-parity-observer-proof-preflight.json"));
for(const p of pre.proposed)if(fs.existsSync(p.path))throw Error("protected prospective path exists "+p.path);
const rawPath=prefix+".raw.log",metaPath=prefix+".meta.jsonl";for(const p of [rawPath,metaPath])if(fs.existsSync(p))throw Error("refusing overwrite "+p);
const raw=fs.openSync(rawPath,"wx",0o600),meta=fs.openSync(metaPath,"wx",0o600);
const start=new Date().toISOString(),mono=process.hrtime.bigint(),errors=[];let bytes=0;const digest=crypto.createHash("sha256");
function write(fd,b){let n=0;while(n<b.length)n+=fs.writeSync(fd,b,n,b.length-n);fs.fsyncSync(fd)}
function record(x){write(meta,Buffer.from(JSON.stringify(x)+"\n"))}
record({event:"start",command:run.command,executable:run.executable,args:run.args,cwd,start,index,head:git("rev-parse","HEAD").trim(),merge:git("rev-parse","MERGE_HEAD").trim(),inputs:files,executionClosure:sha(stream),closureStream:stream,environment:run.environment,classification:"Contemporaneous full tracked execution input map BEFORE spawn; raw log is child bytes in observed stdout/stderr callback order"});
const child=cp.spawn(run.executable,run.args,{cwd,env:process.env,stdio:["ignore","pipe","pipe"]});record({event:"spawn",pid:child.pid,at:new Date().toISOString()});
function capture(b,channel){try{write(raw,b);bytes+=b.length;digest.update(b)}catch(e){errors.push({phase:"raw-write",message:String(e)})}process[channel].write(b)}
child.stdout.on("data",b=>capture(b,"stdout"));child.stderr.on("data",b=>capture(b,"stderr"));child.on("error",e=>errors.push({phase:"spawn",message:String(e)}));
child.on("close",(gateExit,signal)=>{try{fs.fsyncSync(raw);fs.closeSync(raw)}catch(e){errors.push({phase:"raw-close",message:String(e)})}
for(const x of files){const b=x.mode==="120000"?Buffer.from(fs.readlinkSync(x.path)):fs.readFileSync(x.path);if(sha(b)!==x.sha256)errors.push({phase:"post-input-drift",path:x.path})}
for(const p of pre.proposed)if(fs.existsSync(p.path))errors.push({phase:"protected-path-created",path:p.path});
const terminal={event:"terminal",gateExit,signal,loggerExit:errors.length?1:0,errors,start,end:new Date().toISOString(),elapsedSeconds:Number(process.hrtime.bigint()-mono)/1e9,rawBytes:bytes,rawSha256:digest.digest("hex"),executionClosure:sha(stream),inputs:run.inputs,index};
try{record(terminal);fs.closeSync(meta)}catch(e){terminal.loggerExit=1;terminal.errors.push({phase:"meta-terminal",message:String(e)})}
process.stdout.write("\nLOGGER_TERMINAL "+JSON.stringify(terminal)+"\n");process.exitCode=gateExit===0?terminal.loggerExit:(gateExit===null?1:gateExit);
});
